    let mut mru_colors_count = 0usize;
    let mut dxfs_count = 0usize;
    let mut dxfs_attr_map = None::<BTreeMap<String, String>>;
    let mut extension_list_count = 0usize;
    let mut extension_list_attr_map = None::<BTreeMap<String, String>>;
    let mut extension_list_text = None::<String>;
    let mut extension_list_child_names = Vec::<String>::new();
    let mut extension_list_child_attr_maps = Vec::<BTreeMap<String, String>>::new();
    let mut extension_list_child_texts = Vec::<Option<String>>::new();
    let mut extension_list_nested_child_names = Vec::<Vec<String>>::new();
