    let mut extension_list_nested_child_texts = Vec::<Vec<Option<String>>>::new();
    let mut extension_list_great_grandchild_names = Vec::<Vec<Vec<String>>>::new();
    let mut extension_list_great_grandchild_attr_maps =
        Vec::<Vec<Vec<BTreeMap<String, String>>>>::new();
    let mut extension_list_great_grandchild_texts = Vec::<Vec<Vec<Option<String>>>>::new();
    let mut extension_list_great_great_grandchild_names = Vec::<Vec<Vec<Vec<String>>>>::new();
    let mut extension_list_great_great_grandchild_attr_maps =
        Vec::<Vec<Vec<Vec<BTreeMap<String, String>>>>>::new();
    let mut extension_list_great_great_grandchild_texts =
        Vec::<Vec<Vec<Vec<Option<String>>>>>::new();
    let mut num_fmts_attr_map = None::<BTreeMap<String, String>>;
