    let mut reader = Reader::from_reader(Cursor::new(theme_xml));
    reader.config_mut().trim_text(true);
    let mut buffer = Vec::new();
    let mut saw_root = false;
    let mut element_stack = Vec::<String>::new();
    let mut root_name = None::<String>;
    let mut root_attr_map = BTreeMap::<String, String>::new();
    let mut theme_name = None::<String>;
    let mut root_text = None::<String>;
    let mut theme_elements_text = None::<String>;
    let mut color_scheme_text = None::<String>;
    let mut font_scheme_text = None::<String>;
    let mut format_scheme_text = None::<String>;
