    macro_rules! set_active_group_field {
        ($field:ident, $value:expr) => {
            if let Some(group_index) = active_chart_group_index
                && let Some(group) = groups.get_mut(group_index)
            {
                group.$field = $value;
            }
        };
    }

    let parse_u32_val_attr = |element: &BytesStart<'_>,
                              reader: &Reader<Cursor<&[u8]>>,
                              context: &str|
     -> OmResult<Option<u32>> {
        for attr in element.attributes() {
            let attr = attr.map_err(xml_error)?;
            if attr.key.as_ref() != b"val" {
                continue;
            }
            let value = attr
                .decode_and_unescape_value(reader.decoder())
                .map_err(xml_error)?
                .into_owned();
            return value.trim().parse::<u32>().map(Some).map_err(|error| {
                OmError::new(
                    OmErrorCode::Parse,
                    format!("chart {context} value must be an unsigned integer: {value}: {error}"),
                )
            });
        }
        Ok(None)
    };
    let parse_u32_idx_attr = |element: &BytesStart<'_>,
                              reader: &Reader<Cursor<&[u8]>>,
                              context: &str|
     -> OmResult<Option<u32>> {
        for attr in element.attributes() {
            let attr = attr.map_err(xml_error)?;
            if xml_local_name(attr.key.as_ref()) != b"idx" {
                continue;
            }
            let value = attr
                .decode_and_unescape_value(reader.decoder())
                .map_err(xml_error)?
                .into_owned();
            return value.trim().parse::<u32>().map(Some).map_err(|error| {
                OmError::new(
                    OmErrorCode::Parse,
                    format!("chart {context} value must be an unsigned integer: {value}: {error}"),
                )
            });
        }
        Ok(None)
    };

    let parse_string_val_attr =
        |element: &BytesStart<'_>, reader: &Reader<Cursor<&[u8]>>| -> OmResult<Option<String>> {
            for attr in element.attributes() {
                let attr = attr.map_err(xml_error)?;
                if attr.key.as_ref() != b"val" {
                    continue;
                }
                return Ok(Some(
                    attr.decode_and_unescape_value(reader.decoder())
                        .map_err(xml_error)?
                        .into_owned(),
                ));
            }
            Ok(None)
        };
    let parse_bool_val_attr =
        |element: &BytesStart<'_>, reader: &Reader<Cursor<&[u8]>>| -> OmResult<Option<bool>> {
            parse_string_val_attr(element, reader)?
                .map(|value| parse_ooxml_bool(value.as_str()))
                .transpose()
        };
    let parse_i32_val_attr = |element: &BytesStart<'_>,
                              reader: &Reader<Cursor<&[u8]>>,
                              context: &str|
     -> OmResult<Option<i32>> {
        parse_string_val_attr(element, reader)?
            .map(|value| {
                value.trim().parse::<i32>().map_err(|error| {
                    OmError::new(
                        OmErrorCode::Parse,
                        format!("chart {context} value must be an integer: {value}: {error}"),
                    )
                })
            })
            .transpose()
    };
    let parse_f64_val_attr = |element: &BytesStart<'_>,
                              reader: &Reader<Cursor<&[u8]>>,
                              context: &str|
     -> OmResult<Option<f64>> {
        parse_string_val_attr(element, reader)?
            .map(|value| {
                let parsed = value.trim().parse::<f64>().map_err(|error| {
                    OmError::new(
                        OmErrorCode::Parse,
                        format!("chart {context} value must be a number: {value}: {error}"),
                    )
                })?;
                if parsed.is_finite() {
                    Ok(parsed)
                } else {
                    Err(OmError::new(
                        OmErrorCode::Parse,
                        format!("chart {context} value must be finite: {value}"),
                    ))
                }
            })
            .transpose()
    };

    let parse_display_blanks_as = |element: &BytesStart<'_>,
                                   reader: &Reader<Cursor<&[u8]>>,
                                   current: Option<ChartDisplayBlanksAs>|
     -> OmResult<Option<ChartDisplayBlanksAs>> {
        Ok(match parse_string_val_attr(element, reader)?.as_deref() {
            Some("gap") => Some(ChartDisplayBlanksAs::Gap),
            Some("span") => Some(ChartDisplayBlanksAs::Span),
            Some("zero") => Some(ChartDisplayBlanksAs::Zero),
            Some(_) | None => current,
        })
    };
    let parse_chart_view_3d_child = |local_name: &[u8],
                                     element: &BytesStart<'_>,
                                     reader: &Reader<Cursor<&[u8]>>,
                                     view_3d: &mut Option<ChartView3DModel>|
     -> OmResult<()> {
        let view_3d = view_3d.get_or_insert_with(ChartView3DModel::default);
        match local_name {
            b"rotX" => {
                if let Some(value) = parse_i32_val_attr(element, reader, "3D view rotation X")?
                    && (-90..=90).contains(&value)
                {
                    view_3d.elevation = Some(value as i16);
                }
            }
            b"hPercent" => {
                if let Some(value) = parse_i32_val_attr(element, reader, "3D view height percent")?
                    && (5..=500).contains(&value)
                {
                    view_3d.height_percent = Some(value as u16);
                }
            }
            b"rotY" => {
                if let Some(value) = parse_i32_val_attr(element, reader, "3D view rotation Y")?
                    && (0..=360).contains(&value)
                {
                    view_3d.rotation = Some(value as u16);
                }
            }
            b"depthPercent" => {
                if let Some(value) = parse_i32_val_attr(element, reader, "3D view depth percent")?
                    && (20..=2000).contains(&value)
                {
                    view_3d.depth_percent = Some(value as u16);
                }
            }
            b"rAngAx" => {
                view_3d.right_angle_axes =
                    Some(parse_bool_val_attr(element, reader)?.unwrap_or(true));
            }
            b"perspective" => {
                if let Some(value) = parse_i32_val_attr(element, reader, "3D view perspective")?
                    && (0..=100).contains(&value)
                {
                    view_3d.perspective = Some(value as u16);
                }
            }
            _ => {}
        }
        Ok(())
    };
    let parse_tick_mark = |element: &BytesStart<'_>,
                           reader: &Reader<Cursor<&[u8]>>|
     -> OmResult<Option<ChartTickMark>> {
        Ok(match parse_string_val_attr(element, reader)?.as_deref() {
            Some("cross") => Some(ChartTickMark::Cross),
            Some("in") => Some(ChartTickMark::Inside),
            Some("none") => Some(ChartTickMark::None),
            Some("out") => Some(ChartTickMark::Outside),
            Some(_) | None => None,
        })
    };
