    #[test]
    fn parses_shared_strings_and_worksheet_cells() {
        let shared_strings = parse_shared_strings(
            br#"<?xml version="1.0" encoding="UTF-8"?>
<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <si><t>shared</t></si>
</sst>"#,
        )
        .expect("shared strings");
        let cells = parse_worksheet_cells(
            br#"<?xml version="1.0" encoding="UTF-8"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <sheetData>
    <row r="1">
      <c r="A1"><v>42</v></c>
      <c r="B1" t="b"><v>1</v></c>
      <c r="C1" t="s"><v>0</v></c>
      <c r="D1" t="inlineStr"><is><t>inline</t></is></c>
      <c r="E1" t="e"><v>#DIV/0!</v></c>
    </row>
  </sheetData>
</worksheet>"#,
            &shared_strings,
        )
        .expect("worksheet cells");

        assert_eq!(
            cells.get(&(1, 1)).expect("A1").value,
            CellValue::Number(42.0)
        );
        assert_eq!(cells.get(&(1, 2)).expect("B1").value, CellValue::Bool(true));
        assert_eq!(
            cells.get(&(1, 3)).expect("C1").value,
            CellValue::Text("shared".to_string())
        );
        assert_eq!(
            cells.get(&(1, 4)).expect("D1").value,
            CellValue::Text("inline".to_string())
        );
        assert_eq!(
            cells.get(&(1, 5)).expect("E1").value,
            CellValue::Error(CellError::Div0)
        );
    }

