    #[test]
    fn parse_chart_part_summary_maps_series_to_secondary_axis_group() {
        let chart_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:chart="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:test="urn:axis-delete-collision">
  <c:chart>
    <c:plotArea>
      <c:barChart>
        <c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="1"/>
        <c:ser><c:idx val="0"/><c:order val="0"/><c:val><c:numRef><c:f>Sheet1!$A$1:$A$3</c:f></c:numRef></c:val></c:ser>
        <c:gapWidth val="111"/><c:overlap val="-10"/>
        <c:axId val="10"/><c:axId val="20"/>
      </c:barChart>
      <c:lineChart>
        <c:grouping val="standard"/><c:varyColors val="0"/>
        <c:ser><c:idx val="1"/><c:order val="1"/><c:val><c:numRef><c:f>Sheet1!$B$1:$B$3</c:f></c:numRef></c:val></c:ser>
        <c:dLbls><c:showVal val="1"/></c:dLbls>
        <c:dropLines/>
        <c:axId val="10"/><c:axId val="50"/>
      </c:lineChart>
      <c:catAx><chart:axId test:val="999" val="10"></chart:axId><c:delete test:val="1" val="0"/></c:catAx>
      <c:valAx><test:axId val="97"/><c:axId xmlns:c="urn:not-chart" val="98"/><c:axId val="20"/><test:nested><test:valAx><c:axId val="777"/><c:delete val="1"/></test:valAx></test:nested><test:delete val="1"/></c:valAx>
      <c:valAx><c:axId val="50"/></c:valAx>
    </c:plotArea>
  </c:chart>
</c:chartSpace>"#;
        let summary = super::parse_chart_part_summary(chart_xml).expect("chart summary");

        assert_eq!(summary.axes.len(), 3);
        assert_eq!(summary.axes[0].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.axes[1].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.axes[2].axis_group, ChartAxisGroup::Secondary);
        assert_eq!(summary.axes[0].raw_id.as_deref(), Some("10"));
        assert_eq!(summary.axes[1].raw_id.as_deref(), Some("20"));
        assert_eq!(summary.axes[2].raw_id.as_deref(), Some("50"));
        assert_eq!(summary.axes[0].deleted, Some(false));
        assert!(summary.axes[1..].iter().all(|axis| axis.deleted.is_none()));
        assert_eq!(summary.series.len(), 2);
        assert_eq!(summary.series[0].axis_ids, vec!["10", "20"]);
        assert_eq!(summary.series[0].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.series[1].axis_ids, vec!["10", "50"]);
        assert_eq!(summary.series[1].axis_group, ChartAxisGroup::Secondary);
        assert_eq!(summary.groups.len(), 2);
        assert_eq!(summary.groups[0].raw_name, "barChart");
        assert_eq!(summary.groups[0].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.groups[0].series_raw_indices, vec![0]);
        assert_eq!(summary.groups[0].chart_grouping.as_deref(), Some("clustered"));
        assert_eq!(summary.groups[0].vary_by_categories, Some(true));
        assert_eq!(summary.groups[0].gap_width, Some(111));
        assert_eq!(summary.groups[0].overlap, Some(-10));
        assert_eq!(summary.groups[1].raw_name, "lineChart");
        assert_eq!(summary.groups[1].axis_group, ChartAxisGroup::Secondary);
        assert_eq!(summary.groups[1].series_raw_indices, vec![1]);
        assert_eq!(summary.groups[1].chart_grouping.as_deref(), Some("standard"));
        assert_eq!(summary.groups[1].vary_by_categories, Some(false));
        assert_eq!(
            summary.groups[1]
                .data_labels
                .as_ref()
                .and_then(|labels| labels.show_value),
            Some(true)
        );
        assert_eq!(summary.groups[1].has_drop_lines, Some(true));
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[0]),
            ChartType::Column
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[1]),
            ChartType::Line
        );
    }

    #[test]
    fn parse_chart_part_summary_classifies_scatter_axis_pairs_from_group_bindings() {
        let chart_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
  <c:chart><c:plotArea>
    <c:scatterChart><c:scatterStyle val="lineMarker"/>
      <c:ser><c:idx val="0"/><c:order val="0"/></c:ser>
      <c:axId val="10"/><c:axId val="20"/>
    </c:scatterChart>
    <c:scatterChart><c:scatterStyle val="smoothMarker"/>
      <c:ser><c:idx val="1"/><c:order val="1"/></c:ser>
      <c:axId val="40"/><c:axId val="50"/>
    </c:scatterChart>
    <c:valAx><c:axId val="10"/><c:crossAx val="20"/></c:valAx>
    <c:valAx><c:axId val="40"/><c:crossAx val="50"/></c:valAx>
    <c:valAx><c:axId val="20"/><c:crossAx val="10"/></c:valAx>
    <c:valAx><c:axId val="50"/><c:crossAx val="40"/></c:valAx>
  </c:plotArea></c:chart>
</c:chartSpace>"#;
        let summary = super::parse_chart_part_summary(chart_xml).expect("scatter chart summary");

        assert_eq!(summary.axes.len(), 4);
        for axis_id in ["10", "20"] {
            assert_eq!(
                summary
                    .axes
                    .iter()
                    .find(|axis| axis.raw_id.as_deref() == Some(axis_id))
                    .expect("primary scatter axis")
                    .axis_group,
                ChartAxisGroup::Primary
            );
        }
        for axis_id in ["40", "50"] {
            assert_eq!(
                summary
                    .axes
                    .iter()
                    .find(|axis| axis.raw_id.as_deref() == Some(axis_id))
                    .expect("secondary scatter axis")
                    .axis_group,
                ChartAxisGroup::Secondary
            );
        }
        assert_eq!(summary.groups[0].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.groups[1].axis_group, ChartAxisGroup::Secondary);
        assert_eq!(summary.groups[0].scatter_style.as_deref(), Some("lineMarker"));
        assert_eq!(summary.groups[1].scatter_style.as_deref(), Some("smoothMarker"));
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[0]),
            ChartType::ScatterLines
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[1]),
            ChartType::ScatterSmooth
        );
        assert_eq!(summary.series[0].axis_group, ChartAxisGroup::Primary);
        assert_eq!(summary.series[1].axis_group, ChartAxisGroup::Secondary);
    }

    #[test]
    fn parse_chart_part_summary_preserves_each_group_style_discriminator() {
        let chart_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
  <c:chart><c:plotArea>
    <c:radarChart><c:radarStyle val="filled"/></c:radarChart>
    <c:radarChart><c:radarStyle val="marker"/></c:radarChart>
    <c:ofPieChart><c:ofPieType val="pie"/></c:ofPieChart>
    <c:ofPieChart><c:ofPieType val="bar"/></c:ofPieChart>
    <c:bar3DChart><c:barDir val="col"/><c:grouping val="clustered"/><c:shape val="cylinder"/></c:bar3DChart>
    <c:bar3DChart><c:barDir val="col"/><c:grouping val="clustered"/><c:shape val="cone"/></c:bar3DChart>
    <c:pieChart><c:ser><c:explosion val="10"/></c:ser></c:pieChart>
    <c:pieChart><c:ser><c:explosion val="20"/></c:ser></c:pieChart>
  </c:plotArea></c:chart>
</c:chartSpace>"#;
        let summary = super::parse_chart_part_summary(chart_xml).expect("styled group summary");

        assert_eq!(summary.groups.len(), 8);
        assert_eq!(summary.groups[0].radar_style.as_deref(), Some("filled"));
        assert_eq!(summary.groups[1].radar_style.as_deref(), Some("marker"));
        assert_eq!(summary.groups[2].of_pie_type.as_deref(), Some("pie"));
        assert_eq!(summary.groups[3].of_pie_type.as_deref(), Some("bar"));
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[0]),
            ChartType::RadarFilled
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[1]),
            ChartType::RadarMarkers
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[2]),
            ChartType::PieOfPie
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[3]),
            ChartType::BarOfPie
        );
        assert_eq!(
            summary.groups[4].bar_shape,
            Some(excel_model::ChartBarShape::Cylinder)
        );
        assert_eq!(
            summary.groups[5].bar_shape,
            Some(excel_model::ChartBarShape::ConeToPoint)
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[4]),
            ChartType::CylinderColumnClustered
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[5]),
            ChartType::ConeColumnClustered
        );
        assert_eq!(summary.groups[6].explosion, Some(10));
        assert_eq!(summary.groups[7].explosion, Some(20));
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[6]),
            ChartType::PieExploded
        );
        assert_eq!(
            super::chart_type_from_group_summary(&summary.groups[7]),
            ChartType::PieExploded
        );
    }

    #[test]
    fn parse_chart_part_summary_recognizes_volume_stock_groups_by_ownership() {
        let chart_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
  <c:chart><c:plotArea>
    <c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>
      <c:ser><c:idx val="0"/><c:order val="0"/></c:ser>
      <c:axId val="10"/><c:axId val="20"/>
    </c:barChart>
    <c:stockChart>
      <c:ser><c:idx val="1"/><c:order val="1"/></c:ser>
      <c:ser><c:idx val="2"/><c:order val="2"/></c:ser>
      <c:ser><c:idx val="3"/><c:order val="3"/></c:ser>
      <c:hiLowLines/><c:axId val="10"/><c:axId val="50"/>
    </c:stockChart>
    <c:catAx><c:axId val="10"/><c:crossAx val="20"/></c:catAx>
    <c:valAx><c:axId val="50"/><c:crossAx val="10"/></c:valAx>
    <c:valAx><c:axId val="20"/><c:crossAx val="10"/></c:valAx>
  </c:plotArea></c:chart>
</c:chartSpace>"#;
        let summary = super::parse_chart_part_summary(chart_xml).expect("volume stock summary");

        assert_eq!(
            super::chart_type_from_summary(Some(&summary)),
            ChartType::StockVHLC
        );
        assert_eq!(summary.series[0].chart_group_index, 0);
        assert_eq!(
            summary.series[0].chart_group_name.as_deref(),
            Some("barChart")
        );
        assert!(summary.series[1..].iter().all(|series| {
            series.chart_group_index == 1
                && series.chart_group_name.as_deref() == Some("stockChart")
                && series.axis_group == ChartAxisGroup::Secondary
        }));
        let primary_value = summary
            .axes
            .iter()
            .find(|axis| axis.raw_id.as_deref() == Some("20"))
            .expect("primary volume value axis");
        let secondary_value = summary
            .axes
            .iter()
            .find(|axis| axis.raw_id.as_deref() == Some("50"))
            .expect("secondary price value axis");
        assert_eq!(primary_value.axis_group, ChartAxisGroup::Primary);
        assert_eq!(secondary_value.axis_group, ChartAxisGroup::Secondary);
        assert_eq!(primary_value.cross_axis_raw_id.as_deref(), Some("10"));
        assert_eq!(secondary_value.cross_axis_raw_id.as_deref(), Some("10"));
    }

