    #[test]
    fn parse_chart_part_summary_collects_literal_series_sources() {
        let chart_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
  <c:chart>
    <c:plotArea>
      <c:barChart>
        <c:ser>
          <c:idx val="0"/><c:order val="0"/>
          <c:tx><c:v>Inline &quot;A&amp;B &lt;Q&gt;&quot;</c:v></c:tx>
          <c:cat><c:strLit><c:ptCount val="2"/><c:pt idx="1"><c:v>South &lt;West&gt;</c:v></c:pt><c:pt idx="0"><c:v>North &amp; East</c:v></c:pt></c:strLit></c:cat>
          <c:val><c:numLit><c:ptCount val="5"/><c:pt idx="4"><c:v>20</c:v></c:pt><c:pt idx="2"><c:v>#PYTHON!</c:v></c:pt><c:pt idx="0"><c:v>10</c:v></c:pt><c:pt idx="3"><c:v>#UNKNOWN!</c:v></c:pt><c:pt idx="1"><c:v>#N/A</c:v></c:pt></c:numLit></c:val>
        </c:ser>
      </c:barChart>
    </c:plotArea>
  </c:chart>
</c:chartSpace>"#;
        let summary = super::parse_chart_part_summary(chart_xml).expect("chart summary");
        let series = summary.series.first().expect("series summary");
        assert_eq!(
            series.name_literal,
            Some(ChartSourceLiteralSummary {
                kind: ChartCacheKindSummary::String,
                points: vec![ChartSourceLiteralPointSummary {
                    index: 0,
                    value: "Inline \"A&B <Q>\"".to_string(),
                }],
            })
        );
        assert_eq!(
            series.category_cache,
            Some(ChartCacheSummary {
                kind: ChartCacheKindSummary::Literal,
                point_count: Some(2),
            })
        );
        assert_eq!(
            series.category_literal,
            Some(ChartSourceLiteralSummary {
                kind: ChartCacheKindSummary::String,
                points: vec![
                    ChartSourceLiteralPointSummary {
                        index: 1,
                        value: "South <West>".to_string(),
                    },
                    ChartSourceLiteralPointSummary {
                        index: 0,
                        value: "North & East".to_string(),
                    },
                ],
            })
        );
        assert_eq!(
            series.values_cache,
            Some(ChartCacheSummary {
                kind: ChartCacheKindSummary::Literal,
                point_count: Some(5),
            })
        );
        assert_eq!(
            series.values_literal,
            Some(ChartSourceLiteralSummary {
                kind: ChartCacheKindSummary::Number,
                points: vec![
                    ChartSourceLiteralPointSummary {
                        index: 4,
                        value: "20".to_string(),
                    },
                    ChartSourceLiteralPointSummary {
                        index: 2,
                        value: "#PYTHON!".to_string(),
                    },
                    ChartSourceLiteralPointSummary {
                        index: 0,
                        value: "10".to_string(),
                    },
                    ChartSourceLiteralPointSummary {
                        index: 3,
                        value: "#UNKNOWN!".to_string(),
                    },
                    ChartSourceLiteralPointSummary {
                        index: 1,
                        value: "#N/A".to_string(),
                    },
                ],
            })
        );

        let worksheets = vec![WorksheetModel {
            id: SheetId(1),
            workbook_id: WorkbookId(1),
            name: "Sheet1".to_string(),
            kind: SheetKind::Worksheet,
            visibility: SheetVisibility::Visible,
            relationship_id: None,
            part_uri: None,
        }];
        let model_series = super::chart_series_from_summary(
            Some(&summary),
            WorkbookId(1),
            None,
            &worksheets,
            &DefinedNameTable::default(),
            Some(SheetId(1)),
        );
        let model_series = model_series.first().expect("model series");
        let name = model_series.name.as_ref().expect("literal name");
        assert_eq!(name.raw.text, r#""Inline ""A&B <Q>""""#);
        assert_eq!(
            name.resolved.as_ref(),
            Some(&ReferenceTarget::Value(CellValue::Text(
                "Inline \"A&B <Q>\"".to_string()
            )))
        );
        let x_values = model_series.x_values.as_ref().expect("literal x values");
        assert_eq!(x_values.raw.text, r#"{"North & East","South <West>"}"#);
        let Some(ReferenceTarget::Array(array)) = x_values.resolved.as_ref() else {
            panic!("expected literal category source to resolve to array");
        };
        assert_eq!(array.rows, 1);
        assert_eq!(array.cols, 2);
        assert_eq!(array.values[0], OmValue::Text("North & East".to_string()));
        assert_eq!(array.values[1], OmValue::Text("South <West>".to_string()));

        let values = model_series.values.as_ref().expect("literal values");
        assert_eq!(values.raw.text, "{10,#N/A,#PYTHON!,#UNKNOWN!,20}");
        let Some(ReferenceTarget::Array(array)) = values.resolved.as_ref() else {
            panic!("expected literal value source to resolve to array");
        };
        assert_eq!(array.rows, 1);
        assert_eq!(array.cols, 5);
        assert_eq!(array.values[0], OmValue::Number(10.0));
        assert_eq!(array.values[1], OmValue::Error(CellError::NA));
        assert_eq!(array.values[2], OmValue::Error(CellError::Python));
        assert_eq!(array.values[3], OmValue::Error(CellError::Unknown));
        assert_eq!(array.values[4], OmValue::Number(20.0));
    }

