    #[test]
    fn rewrite_worksheet_xml_rejects_missing_source_xml() {
        let worksheet = WorksheetData {
            cells: BTreeMap::new(),
            source_xml: Vec::new(),
            dirty: true,
            dirty_cells: BTreeSet::new(),
        };

        let error = rewrite_worksheet_xml(&worksheet, None)
            .expect_err("rewrite should fail when worksheet source xml is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("worksheet source xml is missing"));
    }

