    #[test]
    fn should_strip_calc_chain_relationship_matches_by_type_or_normalized_target() {
        let rel_type_xml = br#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/calcChain" Target="worksheets/sheet1.xml"/>"#;
        let mut rel_type_reader =
            quick_xml::Reader::from_reader(std::io::Cursor::new(rel_type_xml));
        let mut rel_type_buffer = Vec::new();
        let rel_type_event = rel_type_reader
            .read_event_into(&mut rel_type_buffer)
            .expect("relationship event");
        let rel_type_element = match rel_type_event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected relationship event: {event:?}"),
        };
        assert!(
            super::should_strip_calc_chain_relationship(
                &rel_type_element,
                rel_type_reader.decoder()
            )
            .expect("should strip by type")
        );

        let rel_target_xml = br#"<Relationship Id="rId2" Type="https://example.com/opaque" Target="/xl/calcChain.xml"/>"#;
        let mut rel_target_reader =
            quick_xml::Reader::from_reader(std::io::Cursor::new(rel_target_xml));
        let mut rel_target_buffer = Vec::new();
        let rel_target_event = rel_target_reader
            .read_event_into(&mut rel_target_buffer)
            .expect("relationship event");
        let rel_target_element = match rel_target_event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected relationship event: {event:?}"),
        };
        assert!(
            super::should_strip_calc_chain_relationship(
                &rel_target_element,
                rel_target_reader.decoder()
            )
            .expect("should strip by target")
        );
    }

    #[test]
    fn should_strip_calc_chain_relationship_returns_false_for_unrelated_relationship() {
        let xml = br#"<Relationship Id="rId3" Type="https://example.com/opaque" Target="../styles.xml"/>"#;
        let mut reader = quick_xml::Reader::from_reader(std::io::Cursor::new(xml));
        let mut buffer = Vec::new();
        let event = reader
            .read_event_into(&mut buffer)
            .expect("relationship event");
        let element = match event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected relationship event: {event:?}"),
        };

        assert!(
            !super::should_strip_calc_chain_relationship(&element, reader.decoder())
                .expect("should not strip unrelated relationship")
        );
    }

    #[test]
    fn should_strip_calc_chain_override_matches_with_or_without_leading_slash() {
        let prefixed_xml =
            br#"<Override PartName="/xl/calcChain.xml" ContentType="application/test"/>"#;
        let mut prefixed_reader =
            quick_xml::Reader::from_reader(std::io::Cursor::new(prefixed_xml));
        let mut prefixed_buffer = Vec::new();
        let prefixed_event = prefixed_reader
            .read_event_into(&mut prefixed_buffer)
            .expect("override event");
        let prefixed_element = match prefixed_event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected override event: {event:?}"),
        };
        assert!(
            super::should_strip_calc_chain_override(&prefixed_element, prefixed_reader.decoder())
                .expect("should strip prefixed override")
        );

        let plain_xml =
            br#"<Override PartName="xl/calcChain.xml" ContentType="application/test"/>"#;
        let mut plain_reader = quick_xml::Reader::from_reader(std::io::Cursor::new(plain_xml));
        let mut plain_buffer = Vec::new();
        let plain_event = plain_reader
            .read_event_into(&mut plain_buffer)
            .expect("override event");
        let plain_element = match plain_event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected override event: {event:?}"),
        };
        assert!(
            super::should_strip_calc_chain_override(&plain_element, plain_reader.decoder())
                .expect("should strip plain override")
        );
    }

    #[test]
    fn should_strip_calc_chain_override_returns_false_for_unrelated_part() {
        let xml = br#"<Override PartName="/xl/styles.xml" ContentType="application/test"/>"#;
        let mut reader = quick_xml::Reader::from_reader(std::io::Cursor::new(xml));
        let mut buffer = Vec::new();
        let event = reader.read_event_into(&mut buffer).expect("override event");
        let element = match event {
            quick_xml::events::Event::Empty(element) => element,
            event => panic!("unexpected override event: {event:?}"),
        };

        assert!(
            !super::should_strip_calc_chain_override(&element, reader.decoder())
                .expect("should not strip unrelated override")
        );
    }

    #[test]
    fn rewrite_tracked_hyperlink_relationship_targets_rewrites_bound_entries_and_preserves_others()
    {
        let rels_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Target="https://old.example" data-extra="1"/>
  <Relationship Id="rId2" Type="https://example.com/relationships/opaque" Target="https://untouched.example" TargetMode="External"/>
</Relationships>"#;

        let rewritten = String::from_utf8(
            super::rewrite_tracked_hyperlink_relationship_targets(
                rels_xml,
                &[WorksheetHyperlinkBinding {
                    reference: "A1".to_string(),
                    relationship_id: "rId1".to_string(),
                    target: "https://new.example".to_string(),
                    target_mode: Some("External".to_string()),
                }],
            )
            .expect("rewrite tracked hyperlink relationships"),
        )
        .expect("relationships xml utf8");

        assert!(rewritten.contains(r#"Id="rId1""#));
        assert!(rewritten.contains(r#"Target="https://new.example""#));
        assert!(rewritten.contains(r#"Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink""#));
        assert!(rewritten.contains(r#"TargetMode="External""#));
        assert!(rewritten.contains(r#"data-extra="1""#));
        assert!(rewritten.contains(r#"Id="rId2""#));
        assert!(rewritten.contains(r#"Type="https://example.com/relationships/opaque""#));
        assert!(rewritten.contains(r#"Target="https://untouched.example""#));
    }

