    #[test]
    fn collect_workbook_support_parts_rejects_missing_explicit_styles_part() {
        let mut package = OpcPackage::from_bytes(&workbook_with_styles_and_theme_bytes())
            .expect("base workbook package");
        package.remove_part("xl/styles.xml");

        let error = super::collect_workbook_support_parts(
            &[super::RelationshipEntry {
                id: "rId2".to_string(),
                relationship_type: STYLES_RELATIONSHIP_TYPE.to_string(),
                target: "xl/styles.xml".to_string(),
                target_mode: None,
            }],
            &package,
        )
        .expect_err("collect should fail when explicit styles part is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("explicit styles part is missing"));
        assert!(error.message.contains("xl/styles.xml"));
    }

    #[test]
    fn collect_workbook_support_parts_rejects_missing_explicit_theme_part() {
        let mut package = OpcPackage::from_bytes(&workbook_with_styles_and_theme_bytes())
            .expect("base workbook package");
        package.remove_part("xl/theme/theme1.xml");

        let error = super::collect_workbook_support_parts(
            &[super::RelationshipEntry {
                id: "rId3".to_string(),
                relationship_type: THEME_RELATIONSHIP_TYPE.to_string(),
                target: "xl/theme/theme1.xml".to_string(),
                target_mode: None,
            }],
            &package,
        )
        .expect_err("collect should fail when explicit theme part is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("explicit theme part is missing"));
        assert!(error.message.contains("xl/theme/theme1.xml"));
    }

    #[test]
    fn ensure_support_parts_present_rejects_missing_explicit_workbook_relationships_part() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_styles_and_theme_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let mut package = loaded.package.clone();
        package.remove_part("xl/_rels/workbook.xml.rels");

        let error = super::ensure_support_parts_present(&package, &loaded.support_parts)
            .expect_err("ensure should fail when workbook relationships part is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(
            error
                .message
                .contains("explicit workbook relationships part is missing")
        );
        assert!(error.message.contains("xl/_rels/workbook.xml.rels"));
    }

    #[test]
    fn ensure_support_parts_present_rejects_styles_relationship_target_drift_in_workbook_rels() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_styles_and_theme_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let mut package = loaded.package.clone();
        let workbook_rels = String::from_utf8(
            package
                .part("xl/_rels/workbook.xml.rels")
                .expect("workbook rels part")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8")
        .replace(r#"Target="styles.xml""#, r#"Target="styles2.xml""#);
        package
            .replace_part_bytes("xl/_rels/workbook.xml.rels", workbook_rels.into_bytes())
            .expect("replace workbook rels");

        let error = super::ensure_support_parts_present(&package, &loaded.support_parts)
            .expect_err("ensure should fail when styles relationship target drifts");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("rId2"));
        assert!(error.message.contains("xl/_rels/workbook.xml.rels"));
        assert!(error.message.contains("xl/styles.xml"));
        assert!(error.message.contains("xl/styles2.xml"));
    }

