    #[test]
    fn load_collects_theme_extra_and_custom_color_lists_without_object_defaults_in_theme_summary() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&workbook_with_styles_and_theme_bytes())
            .expect("base workbook package");
        let theme_xml = String::from_utf8(
            package
                .part("xl/theme/theme1.xml")
                .expect("theme part")
                .bytes
                .clone(),
        )
        .expect("theme xml utf8")
        .replace(
            "  <a:objectDefaults/>\n",
            "  <a:extraClrSchemeLst/>\n  <a:custClrLst/>\n",
        );
        package
            .replace_part_bytes("xl/theme/theme1.xml", theme_xml.into_bytes())
            .expect("replace theme part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let theme_summary = loaded
            .support_parts
            .theme_summaries
            .get("xl/theme/theme1.xml")
            .expect("typed theme summary");

        assert_eq!(
            theme_summary.root_child_names,
            vec![
                "themeElements".to_string(),
                "extraClrSchemeLst".to_string(),
                "custClrLst".to_string(),
            ]
        );
        assert!(!theme_summary.has_object_defaults);
        assert!(theme_summary.has_extra_color_scheme_list);
        assert!(theme_summary.has_custom_color_list);
        assert!(!theme_summary.has_extension_list);
    }

