    #[test]
    fn load_collects_reordered_table_styles_and_colors_root_order_in_styles_summary() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&workbook_with_styles_and_theme_bytes())
            .expect("base workbook package");
        let styles_xml = String::from_utf8(
            package
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
        .replace(
            "  <tableStyles count=\"0\" defaultTableStyle=\"TableStyleMedium2\" defaultPivotStyle=\"PivotStyleMedium9\"/>\n",
            "  <tableStyles count=\"0\" defaultTableStyle=\"TableStyleMedium2\" defaultPivotStyle=\"PivotStyleMedium9\"/>\n  <colors><indexedColors/><mruColors/></colors>\n",
        );
        package
            .replace_part_bytes("xl/styles.xml", styles_xml.into_bytes())
            .expect("replace styles part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");

        assert_eq!(
            styles_summary.root_child_names,
            vec![
                "fonts".to_string(),
                "fills".to_string(),
                "borders".to_string(),
                "cellStyleXfs".to_string(),
                "cellStyles".to_string(),
                "cellXfs".to_string(),
                "tableStyles".to_string(),
                "colors".to_string(),
            ]
        );
        assert!(styles_summary.has_colors);
        assert_eq!(
            styles_summary.colors_child_names,
            vec!["indexedColors".to_string(), "mruColors".to_string()]
        );
        assert!(styles_summary.has_table_styles_count_attr);
        assert!(styles_summary.table_styles.is_some());
    }

    #[test]
    fn load_collects_reordered_table_styles_and_empty_colors_root_order_in_styles_summary() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&workbook_with_styles_and_theme_bytes())
            .expect("base workbook package");
        let styles_xml = String::from_utf8(
            package
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
        .replace(
            "  <tableStyles count=\"0\" defaultTableStyle=\"TableStyleMedium2\" defaultPivotStyle=\"PivotStyleMedium9\"/>\n",
            "  <tableStyles count=\"0\" defaultTableStyle=\"TableStyleMedium2\" defaultPivotStyle=\"PivotStyleMedium9\"/>\n  <colors/>\n",
        );
        package
            .replace_part_bytes("xl/styles.xml", styles_xml.into_bytes())
            .expect("replace styles part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");
        let table_styles = styles_summary
            .table_styles
            .as_ref()
            .expect("table styles summary");

        assert_eq!(
            styles_summary.root_child_names,
            vec![
                "fonts".to_string(),
                "fills".to_string(),
                "borders".to_string(),
                "cellStyleXfs".to_string(),
                "cellStyles".to_string(),
                "cellXfs".to_string(),
                "tableStyles".to_string(),
                "colors".to_string(),
            ]
        );
        assert!(styles_summary.has_colors);
        assert!(styles_summary.colors_child_names.is_empty());
        assert!(!styles_summary.has_indexed_colors);
        assert!(!styles_summary.has_mru_colors);
        assert!(!styles_summary.has_dxfs);
        assert!(!styles_summary.has_extension_list);
        assert!(styles_summary.has_table_styles_count_attr);
        assert_eq!(
            table_styles.default_table_style.as_deref(),
            Some("TableStyleMedium2")
        );
        assert_eq!(
            table_styles.default_pivot_style.as_deref(),
            Some("PivotStyleMedium9")
        );
        assert!(table_styles.style_names.is_empty());
        assert!(table_styles.style_attr_maps.is_empty());
    }

