    #[test]
    fn load_collects_xf_alignment_and_protection_in_styles_summary() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_xf_alignment_and_protection_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");

        assert!(styles_summary.cell_style_xfs[0].apply_alignment);
        assert!(styles_summary.cell_style_xfs[0].apply_protection);
        assert_eq!(
            styles_summary.cell_style_xfs[0].alignment_attrs.as_ref(),
            Some(&BTreeMap::from([
                ("horizontal".to_string(), "center".to_string()),
                ("wrapText".to_string(), "1".to_string()),
            ]))
        );
        assert_eq!(
            styles_summary.cell_style_xfs[0].protection_attrs.as_ref(),
            Some(&BTreeMap::from([
                ("hidden".to_string(), "1".to_string()),
                ("locked".to_string(), "0".to_string()),
            ]))
        );
        assert!(styles_summary.cell_xfs[1].apply_alignment);
        assert!(styles_summary.cell_xfs[1].apply_protection);
        assert_eq!(
            styles_summary.cell_xfs[1].alignment_attrs.as_ref(),
            Some(&BTreeMap::from([
                ("horizontal".to_string(), "center".to_string()),
                ("vertical".to_string(), "top".to_string()),
            ]))
        );
        assert_eq!(
            styles_summary.cell_xfs[1].protection_attrs.as_ref(),
            Some(&BTreeMap::from([("locked".to_string(), "0".to_string())]))
        );
    }

