    #[test]
    fn load_collects_cell_xf_without_xf_id_and_with_alignment_protection_in_styles_summary() {
        let codec = XlsxCodec;
        let mut package =
            OpcPackage::from_bytes(&workbook_with_xf_alignment_and_protection_bytes())
                .expect("base workbook package");
        let styles_xml = String::from_utf8(
            package
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
        .replace(
            r#"    <xf numFmtId="14" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1" applyAlignment="1" applyProtection="1"><alignment horizontal="center" vertical="top"/><protection locked="0"/></xf>"#,
            r#"    <xf numFmtId="14" fontId="0" fillId="0" borderId="0" applyNumberFormat="1" applyAlignment="1" applyProtection="1"><alignment horizontal="center" vertical="top"/><protection locked="0"/></xf>"#,
        );
        package
            .replace_part_bytes("xl/styles.xml", styles_xml.into_bytes())
            .expect("replace styles part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");

        assert_eq!(styles_summary.cell_xfs[1].xf_id, None);
        assert!(styles_summary.cell_xfs[1].apply_alignment);
        assert!(styles_summary.cell_xfs[1].apply_protection);
        assert_eq!(
            styles_summary.cell_xfs[1].alignment_attrs.as_ref(),
            Some(&BTreeMap::from([
                ("horizontal".to_string(), "center".to_string()),
                ("vertical".to_string(), "top".to_string()),
            ]))
        );
        assert_eq!(
            styles_summary.cell_xfs[1].protection_attrs.as_ref(),
            Some(&BTreeMap::from([("locked".to_string(), "0".to_string())]))
        );
    }

