    #[test]
    fn load_collects_explicit_worksheet_comment_support_parts() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_hyperlink_comment_and_calc_chain_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        assert_eq!(
            loaded.support_parts.calc_chain_part_uri.as_deref(),
            Some("xl/calcChain.xml")
        );
        assert_eq!(
            loaded
                .support_parts
                .calc_chain_relationship
                .as_ref()
                .map(|relationship| (relationship.id.as_str(), relationship.target.as_str())),
            Some(("rId2", "xl/calcChain.xml"))
        );
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .expect("worksheet support parts");

        assert_eq!(
            worksheet_support.relationships_part_uri.as_deref(),
            Some("xl/worksheets/_rels/sheet1.xml.rels")
        );
        assert_eq!(
            worksheet_support.comment_part_uris,
            vec!["xl/comments1.xml".to_string()]
        );
        assert_eq!(
            worksheet_support
                .comment_anchor_refs
                .get("xl/comments1.xml")
                .cloned(),
            Some(vec!["A1".to_string()])
        );
        let comment_summary = worksheet_support
            .comment_summaries
            .get("xl/comments1.xml")
            .expect("comment summary");
        assert_eq!(comment_summary.root_name, "comments");
        assert_eq!(
            comment_summary
                .root_attr_map
                .get("xmlns")
                .map(String::as_str),
            Some("http://schemas.openxmlformats.org/spreadsheetml/2006/main")
        );
        assert_eq!(
            comment_summary.root_child_names,
            vec!["authors".to_string(), "commentList".to_string()]
        );
        assert!(comment_summary.root_extra_child_xmls.is_empty());
        assert_eq!(comment_summary.authors_attr_map, Some(BTreeMap::new()));
        assert_eq!(comment_summary.comment_list_attr_map, Some(BTreeMap::new()));
        assert_eq!(comment_summary.authors, vec!["Codex".to_string()]);
        assert_eq!(
            comment_summary.comments,
            vec![WorksheetCommentSummary {
                reference: "A1".to_string(),
                author_id: Some(0),
                attr_map: BTreeMap::from([
                    ("authorId".to_string(), "0".to_string()),
                    ("ref".to_string(), "A1".to_string()),
                ]),
                text: "Preserve me".to_string(),
                text_xml: Some(r#"<t>Preserve me</t>"#.to_string()),
            }]
        );
        assert_eq!(
            worksheet_support.vml_drawing_part_uris,
            vec!["xl/drawings/vmlDrawing1.vml".to_string()]
        );
        let vml_summary = worksheet_support
            .vml_drawing_summaries
            .get("xl/drawings/vmlDrawing1.vml")
            .expect("vml drawing summary");
        assert_eq!(vml_summary.root_name, "xml");
        assert_eq!(
            vml_summary.root_attr_map.get("xmlns:v").map(String::as_str),
            Some("urn:schemas-microsoft-com:vml")
        );
        assert_eq!(vml_summary.root_child_names, vec!["v:shape".to_string()]);
        assert!(vml_summary.root_non_shape_xmls.is_empty());
        assert_eq!(vml_summary.shape_ids, vec!["CommentShape".to_string()]);
        assert_eq!(
            vml_summary.shape_attr_maps,
            vec![BTreeMap::from([(
                "id".to_string(),
                "CommentShape".to_string(),
            )])]
        );
        assert_eq!(vml_summary.shape_inner_xmls, vec![String::new()]);
        assert_eq!(
            worksheet_support.hyperlink_relationship_ids,
            vec!["rId1".to_string()]
        );
        assert_eq!(
            worksheet_support.hyperlink_summaries,
            vec![WorksheetHyperlinkSummary {
                reference: "A1".to_string(),
                relationship_id: Some("rId1".to_string()),
                location: None,
                display: None,
                tooltip: None,
            }]
        );
        assert_eq!(worksheet_support.hyperlink_refs, vec!["A1".to_string()]);
        assert_eq!(
            worksheet_support.hyperlink_bindings,
            vec![WorksheetHyperlinkBinding {
                reference: "A1".to_string(),
                relationship_id: "rId1".to_string(),
                target: "https://example.com".to_string(),
                target_mode: Some("External".to_string()),
            }]
        );
        assert_eq!(
            worksheet_support.legacy_drawing_relationship_ids,
            vec!["rId2".to_string()]
        );
        assert_eq!(
            worksheet_support.legacy_drawing_relationships,
            vec![WorksheetRelationshipBinding {
                relationship_id: "rId2".to_string(),
                target: "xl/drawings/vmlDrawing1.vml".to_string(),
            }]
        );
        assert_eq!(
            worksheet_support.comment_relationship_ids,
            vec!["rId3".to_string()]
        );
        assert_eq!(
            worksheet_support.comment_relationships,
            vec![WorksheetRelationshipBinding {
                relationship_id: "rId3".to_string(),
                target: "xl/comments1.xml".to_string(),
            }]
        );
    }

