    #[test]
    fn preserves_row_cell_and_formula_attributes_during_dirty_save() {
        let codec = XlsxCodec;
        let input = workbook_with_preserved_sheet_metadata_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let initial_formula_text = loaded
            .state
            .cell(sheet_id, 1, 2)
            .expect("B1")
            .formula
            .as_ref()
            .expect("B1 formula")
            .text
            .clone();
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(2.0)),
            )
            .expect("set value");

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let sheet_xml = String::from_utf8(
            OpcPackage::from_bytes(&saved)
                .expect("package")
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");

        assert!(sheet_xml.contains(r#"<row r="1" spans="1:2" ht="24" customHeight="1">"#));
        assert!(sheet_xml.contains(r#"<c r="A1" s="5" cm="2" vm="3"><v>2</v></c>"#));
        assert!(sheet_xml.contains(r#"<c r="B1""#));
        assert!(sheet_xml.contains(r#"cm="4""#));
        assert!(sheet_xml.contains(r#"t="str""#));
        assert!(sheet_xml.contains(r#"<f t="shared" ref="B1:B2" si="0">"#));
        assert!(sheet_xml.contains(r#"<row r="3" ht="30" customHeight="1"/>"#));
        assert!(sheet_xml.contains(r#"<mergeCells count="1">"#));
        assert!(sheet_xml.contains(r#"<mergeCell ref="D4:E5"/>"#));

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reload workbook");
        assert_eq!(
            reopened
                .state
                .cell(reopened.state.worksheets[0].id, 1, 1)
                .expect("A1")
                .value,
            CellValue::Number(2.0)
        );
        assert_eq!(
            reopened
                .state
                .cell(reopened.state.worksheets[0].id, 1, 2)
                .expect("B1")
                .formula
                .as_ref()
                .expect("B1 formula")
                .text,
            initial_formula_text
        );
    }

