    #[test]
    fn invalidates_calc_chain_but_preserves_hyperlink_and_comment_artifacts_during_dirty_save() {
        let codec = XlsxCodec;
        let input = workbook_with_hyperlink_comment_and_calc_chain_bytes();
        let original_package = OpcPackage::from_bytes(&input).expect("original package");
        let original_workbook_rels = String::from_utf8(
            original_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("original workbook rels")
                .bytes
                .clone(),
        )
        .expect("original workbook rels utf8");
        assert!(original_workbook_rels.contains("calcChain.xml"));
        let original_sheet_rels = original_package
            .part("xl/worksheets/_rels/sheet1.xml.rels")
            .expect("sheet rels")
            .bytes
            .clone();
        let original_comments = original_package
            .part("xl/comments1.xml")
            .expect("comments part")
            .bytes
            .clone();
        let original_vml = original_package
            .part("xl/drawings/vmlDrawing1.vml")
            .expect("vml drawing")
            .bytes
            .clone();

        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let original_package_rels_source_bytes = loaded
            .support_parts
            .package_relationships_part_source_bytes
            .as_ref()
            .expect("package relationships source bytes")
            .clone();
        let original_package_rels_summary = loaded
            .support_parts
            .package_relationships_summary
            .as_ref()
            .expect("package relationships summary")
            .clone();
        let original_content_types_source_bytes = loaded
            .support_parts
            .content_types_source_bytes
            .as_ref()
            .expect("content types source bytes")
            .clone();
        assert!(
            String::from_utf8(original_content_types_source_bytes.clone())
                .expect("content types source utf8")
                .contains("/xl/calcChain.xml")
        );
        let original_workbook_rels_summary = loaded
            .support_parts
            .workbook_relationships_summary
            .as_ref()
            .expect("workbook relationships summary")
            .clone();
        assert!(
            original_workbook_rels_summary
                .relationship_attr_maps
                .iter()
                .any(|attrs| attrs.get("Type").map(String::as_str)
                    == Some(super::CALC_CHAIN_RELATIONSHIP_TYPE))
        );
        let sheet_id = loaded.state.worksheets[0].id;
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(3.0)),
            )
            .expect("set A1");

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let sheet_xml = String::from_utf8(
            saved_package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");

        assert!(sheet_xml.contains(r#"<c r="A1"><v>3</v></c>"#));
        assert!(sheet_xml.contains(r#"<c r="B1"><f>SUM(1,1)</f><v>2</v></c>"#));
        assert!(sheet_xml.contains("<hyperlinks>"));
        assert!(sheet_xml.contains(r#"<hyperlink ref="A1" r:id="rId1"/>"#));
        assert!(sheet_xml.contains(r#"<legacyDrawing r:id="rId2"/>"#));
        assert!(!saved_package.contains("xl/calcChain.xml"));
        let saved_workbook_rels = String::from_utf8(
            saved_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("saved workbook rels")
                .bytes
                .clone(),
        )
        .expect("saved workbook rels utf8");
        assert!(!saved_workbook_rels.contains("calcChain"));
        let saved_workbook_rels_summary = super::parse_worksheet_relationships_part_summary(
            saved_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("saved workbook rels")
                .bytes
                .as_slice(),
            &["xl"],
        )
        .expect("saved workbook rels summary");
        assert_ne!(saved_workbook_rels_summary, original_workbook_rels_summary);
        assert!(
            saved_workbook_rels_summary
                .relationship_attr_maps
                .iter()
                .all(|attrs| attrs.get("Type").map(String::as_str)
                    != Some(super::CALC_CHAIN_RELATIONSHIP_TYPE))
        );
        let saved_content_types = String::from_utf8(
            saved_package
                .part("[Content_Types].xml")
                .expect("saved content types")
                .bytes
                .clone(),
        )
        .expect("saved content types utf8");
        assert!(!saved_content_types.contains("/xl/calcChain.xml"));
        assert_ne!(
            saved_content_types.as_bytes(),
            original_content_types_source_bytes
        );
        assert_eq!(
            saved_package
                .part("_rels/.rels")
                .expect("saved package rels")
                .bytes,
            original_package_rels_source_bytes
        );
        let saved_package_rels_summary = super::parse_worksheet_relationships_part_summary(
            saved_package
                .part("_rels/.rels")
                .expect("saved package rels")
                .bytes
                .as_slice(),
            &[],
        )
        .expect("saved package rels summary");
        assert_eq!(saved_package_rels_summary, original_package_rels_summary);
        assert_eq!(
            saved_package
                .part("xl/worksheets/_rels/sheet1.xml.rels")
                .expect("saved sheet rels")
                .bytes,
            original_sheet_rels
        );
        assert_eq!(
            saved_package
                .part("xl/comments1.xml")
                .expect("saved comments part")
                .bytes,
            original_comments
        );
        assert_eq!(
            saved_package
                .part("xl/drawings/vmlDrawing1.vml")
                .expect("saved vml drawing")
                .bytes,
            original_vml
        );

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reload workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 1, 1)
                .expect("A1")
                .value,
            CellValue::Number(3.0)
        );
        let formula_cell = reopened.state.cell(reopened_sheet_id, 1, 2).expect("B1");
        assert_eq!(
            formula_cell.formula.as_ref().expect("B1 formula").text,
            "SUM(1,1)"
        );
        assert_eq!(formula_cell.value, CellValue::Number(2.0));
    }

    #[test]
    fn dirty_calc_chain_invalidation_preserves_package_xml_structure() {
        let codec = XlsxCodec;
        let mut package =
            OpcPackage::from_bytes(&workbook_with_hyperlink_comment_and_calc_chain_bytes())
                .expect("base workbook package");
        let content_types = String::from_utf8(
            package
                .part("[Content_Types].xml")
                .expect("content types part")
                .bytes
                .clone(),
        )
        .expect("content types utf8")
        .replace(
            r#"<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">"#,
            r#"<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types" data-root="keep"><ext preserve="content-types"/>"#,
        )
        .replace(
            r#"<Default Extension="xml" ContentType="application/xml"/>"#,
            r#"<Default Extension="xml" ContentType="application/xml" data-default="keep"/>"#,
        )
        .replace(
            r#"<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>"#,
            r#"<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml" data-workbook="keep"/>"#,
        );
        package
            .replace_part_bytes("[Content_Types].xml", content_types.into_bytes())
            .expect("replace content types");
        let expected_content_types = super::strip_calc_chain_content_type_override(
            package
                .part("[Content_Types].xml")
                .expect("expected content types")
                .bytes
                .as_slice(),
        )
        .expect("strip calc chain content type override");
        let package_rels = String::from_utf8(
            package
                .part("_rels/.rels")
                .expect("package rels part")
                .bytes
                .clone(),
        )
        .expect("package rels utf8")
        .replace(
            r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">"#,
            r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships" data-root="keep"><ext preserve="package-rels"/>"#,
        )
        .replace(
            r#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>"#,
            r#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml" data-package="keep"><ext preserve="workbook"/></Relationship>"#,
        );
        package
            .replace_part_bytes("_rels/.rels", package_rels.into_bytes())
            .expect("replace package rels");
        let expected_package_rels = package
            .part("_rels/.rels")
            .expect("expected package rels")
            .bytes
            .clone();
        let workbook_rels = String::from_utf8(
            package
                .part("xl/_rels/workbook.xml.rels")
                .expect("workbook rels part")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8")
        .replace(
            r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">"#,
            r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships" data-root="keep"><ext preserve="workbook-rels"/>"#,
        )
        .replace(
            r#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>"#,
            r#"<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml" data-sheet="keep"><ext preserve="sheet"/></Relationship>"#,
        );
        package
            .replace_part_bytes("xl/_rels/workbook.xml.rels", workbook_rels.into_bytes())
            .expect("replace workbook rels");
        let expected_workbook_rels = super::strip_calc_chain_relationships(
            package
                .part("xl/_rels/workbook.xml.rels")
                .expect("expected workbook rels")
                .bytes
                .as_slice(),
        )
        .expect("strip calc chain relationships");
        let input = package.to_bytes().expect("package bytes");

        let mut loaded = codec
            .load(input.as_slice(), CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(4.0)),
            )
            .expect("set A1");

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_content_types = String::from_utf8(
            saved_package
                .part("[Content_Types].xml")
                .expect("saved content types")
                .bytes
                .clone(),
        )
        .expect("saved content types utf8");
        assert!(saved_content_types.contains(r#"data-root="keep""#));
        assert!(saved_content_types.contains(r#"<ext preserve="content-types"/>"#));
        assert!(saved_content_types.contains(r#"data-default="keep""#));
        assert!(saved_content_types.contains(r#"data-workbook="keep""#));
        assert!(!saved_content_types.contains("calcChain.xml"));
        assert_eq!(
            saved_package
                .part("[Content_Types].xml")
                .expect("saved content types")
                .bytes,
            expected_content_types
        );
        assert_eq!(
            saved_package
                .part("_rels/.rels")
                .expect("saved package rels")
                .bytes,
            expected_package_rels
        );
        let saved_workbook_rels = String::from_utf8(
            saved_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("saved workbook rels")
                .bytes
                .clone(),
        )
        .expect("saved workbook rels utf8");
        assert!(saved_workbook_rels.contains(r#"data-root="keep""#));
        assert!(saved_workbook_rels.contains(r#"<ext preserve="workbook-rels"/>"#));
        assert!(saved_workbook_rels.contains(r#"data-sheet="keep""#));
        assert!(saved_workbook_rels.contains(r#"<ext preserve="sheet"/>"#));
        assert!(!saved_workbook_rels.contains("calcChain"));
        assert_eq!(
            saved_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("saved workbook rels")
                .bytes,
            expected_workbook_rels
        );
    }

