    #[test]
    fn dirty_save_restores_legacy_drawing_attr_map_for_blank_hyperlink_comment_anchor_without_legacy_ref_lists()
     {
        let codec = XlsxCodec;
        let input = workbook_with_blank_hyperlink_comment_anchor_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let expected_summary = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .map(|worksheet_support| worksheet_support.legacy_drawing_summaries.clone())
            .expect("worksheet legacyDrawing summaries");
        let worksheet_support = loaded
            .worksheet_support_parts
            .get_mut(&sheet_id)
            .expect("worksheet support parts");
        worksheet_support.hyperlink_refs.clear();
        worksheet_support.comment_anchor_refs.clear();
        let sheet_xml = String::from_utf8(
            loaded
                .package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8")
        .replace(
            r#"<legacyDrawing r:id="rId2"/>"#,
            r#"<legacyDrawing r:id="rId2" data-extra="2"/>"#,
        );
        loaded
            .package
            .replace_part_bytes("xl/worksheets/sheet1.xml", sheet_xml.into_bytes())
            .expect("replace sheet xml");
        loaded.state.insert_cell(
            sheet_id,
            3,
            3,
            CellData {
                value: CellValue::Number(4.0),
                formula: None,
                style_id: None,
            },
        );
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 3, 3),
                &office_common::OmArray::scalar(office_common::OmValue::Empty),
            )
            .expect("blank C3");
        assert!(loaded.state.cell(sheet_id, 3, 3).is_none());

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_sheet_xml_bytes = saved_package
            .part("xl/worksheets/sheet1.xml")
            .expect("saved sheet part")
            .bytes
            .as_slice();
        let saved_sheet_xml =
            String::from_utf8(saved_sheet_xml_bytes.to_vec()).expect("saved sheet xml utf8");
        let saved_comments_xml = String::from_utf8(
            saved_package
                .part("xl/comments1.xml")
                .expect("saved comments part")
                .bytes
                .clone(),
        )
        .expect("saved comments xml utf8");
        let saved_summary = crate::parse_worksheet_legacy_drawing_summaries(saved_sheet_xml_bytes)
            .expect("saved worksheet legacyDrawing summaries");

        assert_eq!(saved_summary, expected_summary);
        assert!(saved_sheet_xml.contains(r#"<c r="C3"/>"#));
        assert!(saved_sheet_xml.contains(r#"<hyperlink ref="C3" r:id="rId1"/>"#));
        assert!(saved_comments_xml.contains(r#"ref="C3""#));
        assert!(saved_sheet_xml.contains(r#"<legacyDrawing r:id="rId2"/>"#));
        assert!(!saved_sheet_xml.contains(r#"<legacyDrawing r:id="rId2" data-extra="2"/>"#));

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reopen workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert!(reopened.state.cell(reopened_sheet_id, 3, 3).is_none());
    }

