    fn assert_dirty_save_preserves_theme_xml_for_mutated_input(input: Vec<u8>) {
        let codec = XlsxCodec;
        let original_package = OpcPackage::from_bytes(&input).expect("original package");
        let original_theme = original_package
            .part("xl/theme/theme1.xml")
            .expect("theme part")
            .bytes
            .clone();

        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(8.0)),
            )
            .expect("set A1");

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let sheet_xml = String::from_utf8(
            saved_package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");

        assert!(sheet_xml.contains(r#"<c r="A1" s="1"><v>8</v></c>"#));
        assert!(sheet_xml.contains(r#"<c r="B1" s="2"><f>SUM(1,1)</f><v>2</v></c>"#));
        assert_eq!(
            saved_package
                .part("xl/theme/theme1.xml")
                .expect("saved theme")
                .bytes,
            original_theme
        );

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reload workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 1, 1)
                .expect("A1")
                .value,
            CellValue::Number(8.0)
        );
        let formula_cell = reopened.state.cell(reopened_sheet_id, 1, 2).expect("B1");
        assert_eq!(formula_cell.style_id, Some(StyleId(2)));
        assert_eq!(
            formula_cell.formula.as_ref().expect("B1 formula").text,
            "SUM(1,1)"
        );
        assert_eq!(formula_cell.value, CellValue::Number(2.0));
    }

