    #[test]
    fn saves_inserted_styled_blank_cells_without_touching_style_artifacts() {
        let codec = XlsxCodec;
        let input = workbook_with_styles_and_theme_bytes();
        let original_package = OpcPackage::from_bytes(&input).expect("original package");
        let original_styles = original_package
            .part("xl/styles.xml")
            .expect("styles part")
            .bytes
            .clone();
        let original_theme = original_package
            .part("xl/theme/theme1.xml")
            .expect("theme part")
            .bytes
            .clone();

        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        loaded.state.insert_cell(
            sheet_id,
            1,
            3,
            CellData {
                value: CellValue::Blank,
                formula: None,
                style_id: Some(StyleId(3)),
            },
        );

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let sheet_xml = String::from_utf8(
            saved_package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");

        assert!(sheet_xml.contains(r#"<c r="C1" s="3"/>"#));
        assert_eq!(
            saved_package
                .part("xl/styles.xml")
                .expect("saved styles")
                .bytes,
            original_styles
        );
        assert_eq!(
            saved_package
                .part("xl/theme/theme1.xml")
                .expect("saved theme")
                .bytes,
            original_theme
        );

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reload workbook");
        let inserted = reopened
            .state
            .cell(reopened.state.worksheets[0].id, 1, 3)
            .expect("C1");
        assert_eq!(inserted.value, CellValue::Blank);
        assert_eq!(inserted.style_id, Some(StyleId(3)));
    }

    #[test]
    fn save_rejects_missing_explicit_styles_part() {
        let codec = XlsxCodec;
        let input = workbook_with_styles_and_theme_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        loaded.package.remove_part("xl/styles.xml");
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(9.0)),
            )
            .expect("set value");

        let error = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect_err("save should fail when explicit styles part is missing");
        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("xl/styles.xml"));
    }

    #[test]
    fn save_rejects_missing_explicit_styles_relationship_id_in_workbook_rels() {
        let codec = XlsxCodec;
        let input = workbook_with_styles_and_theme_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let workbook_rels = String::from_utf8(
            loaded
                .package
                .part("xl/_rels/workbook.xml.rels")
                .expect("workbook rels part")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8")
        .replace(
            r#"  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>"#,
            "",
        );
        loaded
            .package
            .replace_part_bytes("xl/_rels/workbook.xml.rels", workbook_rels.into_bytes())
            .expect("replace workbook rels");
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(9.0)),
            )
            .expect("set value");

        let error = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect_err("save should fail when styles relationship id is missing");
        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("rId2"));
        assert!(error.message.contains("xl/_rels/workbook.xml.rels"));
        assert!(error.message.contains("xl/styles.xml"));
    }

    #[test]
    fn save_rejects_styles_relationship_type_drift_in_workbook_rels() {
        let codec = XlsxCodec;
        let input = workbook_with_styles_and_theme_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let workbook_rels = String::from_utf8(
            loaded
                .package
                .part("xl/_rels/workbook.xml.rels")
                .expect("workbook rels part")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8")
        .replace(
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles",
            "http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme",
        );
        loaded
            .package
            .replace_part_bytes("xl/_rels/workbook.xml.rels", workbook_rels.into_bytes())
            .expect("replace workbook rels");
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, 1),
                &office_common::OmArray::scalar(office_common::OmValue::Number(9.0)),
            )
            .expect("set value");

        let error = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect_err("save should fail when styles relationship type drifts");
        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("rId2"));
        assert!(error.message.contains("xl/_rels/workbook.xml.rels"));
        assert!(error.message.contains(STYLES_RELATIONSHIP_TYPE));
        assert!(error.message.contains(THEME_RELATIONSHIP_TYPE));
    }

